installer-gui-script.script:
function checkMachine() {
  // The arm64 pkg carries an arm64 image. Refuse an Intel Mac here, with a
  // message, rather than letting the postinstall fail with a generic
  // "installation failed" (the x86_64 pkg skips this: Apple silicon runs
  // it under Rosetta, as the updater's docstring explains).
  if ('@ARCH@' == 'arm64' && system.sysctl('hw.optional.arm64') != 1) {
    my.result.title = 'This installer is for Apple silicon Macs';
    my.result.message = 'On an Intel Mac, download the Intel build (the -x86_64 .dmg) from https://github.com/fusedio/fused-render/releases and drag it to Applications.';
    my.result.type = 'Fatal';
    return false;
  }
  return true;
}
